uniform float amzp_cpMap;
uniform float amzp_cpMax;
uniform float amzp_cpInvert;
uniform float amzp_cpContrast;
uniform float amzp_cpAngle;
uniform float amzp_cpCenterX;
uniform float amzp_cpCenterY;
uniform float amzp_cpLength;
uniform float amzp_cpShowMap;
uniform float amzp_overdrawOn;
uniform float amzp_quality;
    float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
    float4 box(int t, float2 sz, float2 uv) {
        float2 ts = 1.0 / sz;
        return (amzTexture(t, uv + ts * float2(-0.5, -0.5)) + amzTexture(t, uv + ts * float2(0.5, -0.5))
              + amzTexture(t, uv + ts * float2(-0.5, 0.5)) + amzTexture(t, uv + ts * float2(0.5, 0.5))) * 0.25;
    }
    float4 lvl(float L, float2 uv) {
        if (L < 0.5) return amzTexture(0, uv);
        if (L < 1.5) return amzTexture(2, uv);
        if (L < 2.5) return amzTexture(3, uv);
        return amzTexture(4, uv);
    }
    float4 at(float L, float2 uv) {
        float L0 = floor(L);
        return mix(lvl(L0, uv), lvl(L0 + 1.0, uv), L - L0);
    }
    float mapAt(float2 uv) {
        float m;
        if (int(amzp_cpMap) == 0) {
            float4 c = amzTexture(1, uv);
            m = luma(c.a > 0.00001 ? c.rgb / c.a : float3(0.0)) * c.a;
        } else if (int(amzp_cpMap) == 1) {
            float4 c = amzTexture(0, uv);
            m = luma(c.a > 0.00001 ? c.rgb / c.a : float3(0.0));
        } else {
            float2 P = float2(uv.x, 1.0 - uv.y) - 0.5 - float2(amzp_cpCenterX, amzp_cpCenterY);
            P.x *= screen.zw.x / max(screen.zw.y, 1.0);
            float d;
            if (int(amzp_cpMap) == 2) {
                float a = radians(amzp_cpAngle);
                d = abs(dot(P, float2(cos(a), sin(a))));
            } else {
                d = length(P);
            }
            m = clamp(d / max(amzp_cpLength, 0.01), 0.0, 1.0);
        }
        m = clamp(m, 0.0, 1.0);
        if ((amzp_cpInvert>0.5)) m = 1.0 - m;
        float k = max(amzp_cpContrast, 0.05);
        m = clamp((m - 0.5) * k + 0.5, 0.0, 1.0);
        return m;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        if (amzPass == 0) { amzOutput = box(0, (screen.zw/1.0), uv); return; }
        if (amzPass == 1) { amzOutput = box(2, (screen.zw/2.0), uv); return; }
        if (amzPass == 2) { amzOutput = box(3, (screen.zw/4.0), uv); return; }
        float4 base = amzTexture(0, uv);
        float amt = mapAt(uv);
        float4 res = base;
        if ((amzp_cpShowMap>0.5)) {
            res = float4(float3(amt) * max(base.a, 0.0), base.a);
        } else {
            float2 S = screen.zw;
            float px = S.x / max(screen.zw.x, 1.0);
            float R = max(amzp_cpMax, 0.0) * px * amt;
            if (R > 0.5) {
                float n = int(amzp_quality) == 0 ? 32.0 : (int(amzp_quality) == 2 ? 128.0 : 64.0);
                float L = clamp(log2(max(R * 1.9 / sqrt(n), 1.0)), 0.0, 2.999);
                float4 acc = float4(0.0);
                float ws = 0.0;
                for (int i = 0; i < 128; i++) {
                    float fi = float(i);
                    if (fi >= n) break;
                    float r = sqrt((fi + 0.5) / n);
                    float a = fi * 2.39996323;
                    float w = exp(-r * r * 2.0);
                    acc += at(L, uv + float2(cos(a), sin(a)) * r * R / S) * w;
                    ws += w;
                }
                res = acc / max(ws, 0.0001);
            }
        }
        if (!(amzp_overdrawOn>0.5)) res *= base.a;
        amzOutput = res;
    }

half4 main(float2 coord) { amzCoord=coord*8.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

